'use strict';
let recipeDraft=null,ingredientDraft=null,recipeFilter='Available',ingredientFilter='All';
const unitLabels={cup:'cups',tbsp:'tablespoons',tsp:'teaspoons','fl oz':'fluid ounces',ml:'milliliters',l:'liters',g:'grams',kg:'kilograms',oz:'ounces',lb:'pounds',each:'each',drop:'drops'};
const unitOptions=(selected)=>CookieEngine.units.map(u=>`<option value="${u}" ${u===selected?'selected':''}>${unitLabels[u]}</option>`).join('');
const sortedRecipes=()=>state.recipes.slice().sort((a,b)=>a.name.localeCompare(b.name));
const sortedIngredients=()=>state.ingredients.slice().sort((a,b)=>a.name.localeCompare(b.name));
const nextId=arr=>Math.max(-1,...arr.map(x=>x.id))+1;
function planningAlerts(){
 const issues=plan.issues||[],archived=plan.archivedRequests||[];
 if(!issues.length&&!archived.length)return '';
 return `<div class="notice error-notice"><strong>${issues.length?'Some totals need attention.':'Archived recipes still have requests.'}</strong> ${issues.length?'Shopping and cost subtotals exclude quantities that cannot yet be converted.':''}<ul>${issues.slice(0,8).map(i=>`<li>${esc(i.recipe)}${i.ingredient?' · '+esc(i.ingredient):''}: ${esc(i.message)}</li>`).join('')}${archived.map(r=>`<li>${esc(r.name)} is archived but still has ${fmt(r.requested)} accepted cookies to fulfill. Existing demand remains in the plan.</li>`).join('')}</ul><button class="text-link" data-go="ingredients">Review ingredient settings →</button></div>`;
}
recipes=function(){
 const available=state.recipes.filter(r=>!r.archived).length;
 const rows=plan.recipePlans.filter(r=>(recipeFilter==='All'||(recipeFilter==='Archived'?r.archived:!r.archived))&&r.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));
 return head('THE BAKER’S RECIPE COLLECTION','Your recipes. Exactly your way.','Create, correct, and organize every recipe. Changes flow into the current baking and shopping plan.',`<button class="btn quiet" data-go="ingredients">Ingredients & prices →</button><button class="btn" data-action="new-recipe">＋ Add recipe</button>`)+
 `<div class="toolbar"><input class="search" id="recipe-search" placeholder="Search your recipes…" aria-label="Search recipes" value="${esc(query)}"><div class="filters">${['Available','Archived','All'].map(f=>`<button class="filter ${recipeFilter===f?'active':''}" data-recipe-filter="${f}">${f}${f==='Available'?' · '+available:''}</button>`).join('')}</div></div><div class="cards">${rows.map((r,n)=>`<button class="recipe-card ${r.archived?'archived-card':''}" data-recipe="${r.id}"><div class="recipe-art" style="background:${['#e8eddf','#efe9df','#ece5d9','#f1e9e0'][n%4]}">${cookie(r.id%8)}</div><div class="recipe-body"><div class="eyebrow" style="font-size:8px">${r.archived?'ARCHIVED RECIPE':r.sourceName?'FAMILY RECIPE COLLECTION':'FROM YOUR KITCHEN'}</div><h3>${esc(r.name)}</h3><div class="recipe-meta"><span>${r.yield} cookies / batch</span><span>${r.missing?'Cost needs attention':money(r.batchCost)+' / batch'}</span></div><div class="recipe-footer">${status(r.archived?'Archived':r.reviewed?'Reviewed':'Needs review')}<span>${r.lines.length} ingredients · Edit →</span></div></div></button>`).join('')}</div>${!rows.length?'<div class="blank">No recipes match this view. Add a recipe or change the filter.</div>':''}
 <section class="panel" style="margin-top:24px"><div class="panel-body"><h2 class="section-title">One imported entry needs a baker’s eye</h2><p class="list-note">“Choc Chip Toffee Bars” has four ingredient rows but no matching batch yield. Review the entry, then turn it into a recipe if it belongs in your collection.</p><button class="btn quiet small" data-action="orphan">Review source entry →</button></div></section><p class="list-note">Archiving removes a recipe from new requests. Existing requests remain visible and counted until you resolve them. Recipe edits apply to this current season.</p>`;
};
function ingredients(){
 const rows=sortedIngredients().filter(i=>i.name.toLowerCase().includes(query.toLowerCase())&&(ingredientFilter==='All'||ingredientFilter==='Missing prices'&&i.price==null||ingredientFilter==='Needs review'&&!i.reviewed||ingredientFilter==='Archived'&&i.archived));
 return head('THE KITCHEN CUPBOARD','A place for every ingredient.','Maintain ingredients, package sizes, prices and pantry stock—even before there are requests.',`<button class="btn" data-action="new-ingredient">＋ Add ingredient</button>`)+
 `<div class="toolbar"><input class="search" id="ingredient-search" placeholder="Search ingredients…" aria-label="Search ingredients" value="${esc(query)}"><div class="filters">${['All','Missing prices','Needs review','Archived'].map(f=>`<button class="filter ${ingredientFilter===f?'active':''}" data-ingredient-filter="${f}">${f}</button>`).join('')}</div></div><section class="panel table-wrap"><table><thead><tr><th>Ingredient</th><th>Purchase package</th><th class="num">Recipe units / package</th><th class="num">Price</th><th class="num">Pantry packages</th><th>Setup</th></tr></thead><tbody>${rows.map(i=>`<tr class="row-click" data-ingredient="${i.id}"><td><strong>${esc(i.name)}</strong><small>${state.recipes.filter(r=>r.lines.some(l=>l.ingredientId===i.id)).length} recipes${i.archived?' · Archived':''}</small></td><td>${esc(i.package||'Package needed')}</td><td class="num">${i.unitsPerPackage>0?fmt(i.unitsPerPackage)+' '+esc(i.unit):'<span class="alert-number">Conversion needed</span>'}</td><td class="num">${i.price==null?'<span class="alert-number">Price needed</span>':money(i.price)}<small>${i.priceKind==='Manual'?esc(i.priceDate||'Manually entered'):i.priceKind==='Illustrative'?'Illustrative price':''}</small></td><td class="num">${fmt(i.pantry||0)}</td><td>${status(i.reviewed?'Reviewed':'Needs review')}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="blank">No ingredients match this view.</div>':''}</section><p class="list-note">Package equivalents are specific to each ingredient. A cup of flour and a cup of chocolate chips do not use the same weight conversion. Prices may be left blank; the app will flag incomplete estimates.</p>`;
}
function settings(){return head('YOUR KITCHEN, YOUR RECORDS','Keep the good work safe.','Save a copy of your recipes, requests, pantry settings and prices before making major changes.')+
 `<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>Your kitchen backup</h2><small>A complete copy of this browser’s current workspace</small></div></div><div class="panel-body"><p class="list-note">Download a backup to keep your corrections or move them to another browser. Restoring replaces this browser’s current workspace.</p><div class="page-buttons"><button class="btn" data-action="backup">Download backup</button><button class="btn quiet" data-action="restore">Restore backup</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden></div></section><section class="panel"><div class="panel-head"><div><h2>About this preview</h2><small>Ready for a baker’s walkthrough</small></div></div><div class="panel-body"><p class="list-note">You can fully manage recipes and ingredients here. This is a private concept with browser-local storage. Shared requests, account invitations and automatic backups will be connected in the finished app. Starting prices are illustrative; imported recipe information needs review.</p><div class="page-buttons"><button class="btn quiet" data-action="reset-confirm">Reset demonstration</button></div></div></section></div><section class="panel"><div class="panel-body"><h2 class="section-title">A useful first walkthrough</h2><ol class="walkthrough"><li><strong>Open a familiar recipe.</strong> Check the yield and original ingredient quantities.</li><li><strong>Make a correction.</strong> Add or remove an ingredient, switch a measurement, or enter your instructions.</li><li><strong>Check the cupboard.</strong> Set a real package size and price, then enter what you already have.</li><li><strong>Review the plan.</strong> Confirm the batch totals and shopping quantities make sense for your kitchen.</li></ol></div></section>`;}
function newRecipeDraft(){return {id:nextId(state.recipes),name:'',yield:24,lines:[],instructions:'',notes:'',reviewed:false,archived:false,baked:0};}
function recipeLineHTML(l,n){
 const i=state.ingredients.find(i=>i.id===l.ingredientId),choices=sortedIngredients().filter(x=>!x.archived||x.id===l.ingredientId);
 return `<div class="ingredient-edit-row"><label><span class="mobile-label">Ingredient</span><select data-line-field="ingredientId" data-line-index="${n}" required aria-label="Ingredient ${n+1}"><option value="">Choose an ingredient…</option>${choices.map(x=>`<option value="${x.id}" ${x.id===l.ingredientId?'selected':''}>${esc(x.name)}${x.archived?' (archived)':''}</option>`).join('')}</select></label><label><span class="mobile-label">Amount</span><input data-line-field="amount" data-line-index="${n}" type="number" min="0.000001" step="any" required value="${l.amount??1}" aria-label="Amount for ingredient ${n+1}"></label><label><span class="mobile-label">Unit</span><select data-line-field="unit" data-line-index="${n}" aria-label="Unit for ingredient ${n+1}">${unitOptions(l.unit||i?.unit||'cup')}</select></label><button class="remove-row" type="button" data-remove-line="${n}" aria-label="Remove ingredient ${n+1}">×</button></div>`;
}
function recipeLiveSummary(){
 if(!recipeDraft)return '';
 let known=0;const problems=[];
 recipeDraft.lines.forEach(l=>{const i=state.ingredients.find(i=>i.id===l.ingredientId);if(!i){problems.push('Choose an ingredient for every row.');return;}const q=CookieEngine.convert(Number(l.amount),l.unit,i.unit,i);if(q==null||!(i.unitsPerPackage>0)){problems.push(`${i.name}: set its ${l.unit}-to-${i.unit} or package conversion in Ingredients & pantry.`);return;}if(i.price==null)problems.push(`${i.name}: price is missing.`);else known+=q/i.unitsPerPackage*i.price;});
 return `<div class="editor-estimate"><span>${problems.length?'Known ingredient cost':'Estimated ingredient cost'} per batch</span><strong>${money(known)}</strong></div>${problems.length?`<div class="notice"><strong>Still needed for complete estimates</strong><ul>${[...new Set(problems)].map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>`:'<p class="list-note">Measurement changes update the cost estimate here. Saving updates every current-season plan.</p>'}`;
}
openRecipe=function(id){recipeDraft=structuredClone(state.recipes.find(r=>r.id===Number(id))||newRecipeDraft());drawRecipeEditor();};
function drawRecipeEditor(){
 const existing=state.recipes.some(r=>r.id===recipeDraft.id);
 modal(modalHead(existing?recipeDraft.name:'A new family favorite','The recipe card is the source for your baking, shopping and cost totals.')+`<form class="modal-body recipe-editor" id="full-recipe-form"><div class="form-grid"><label class="field">Recipe name<input data-recipe-field="name" required maxlength="100" value="${esc(recipeDraft.name)}" placeholder="e.g. Grandma’s ginger cookies"></label><label class="field">Cookies per full batch<input data-recipe-field="yield" required type="number" min="1" max="10000" step="1" value="${recipeDraft.yield}"></label></div><div class="editor-section-head"><h3 class="section-title">Ingredients per batch</h3><button class="text-link" type="button" data-action="ingredient-from-recipe">＋ Create a new ingredient</button></div><div class="ingredient-edit-labels"><span>Ingredient</span><span>Amount</span><span>Unit</span><span></span></div><div id="recipe-lines">${recipeDraft.lines.map(recipeLineHTML).join('')}</div><button class="btn quiet small" type="button" data-action="add-recipe-line">＋ Add ingredient row</button><div id="recipe-live-summary" style="margin-top:20px">${recipeLiveSummary()}</div><label class="field" style="margin-top:22px">Baking instructions<textarea data-recipe-field="instructions" rows="6" maxlength="12000" placeholder="Mixing, oven temperature, baking time, cooling and finishing…">${esc(recipeDraft.instructions)}</textarea></label><label class="field">Baker’s notes<textarea data-recipe-field="notes" maxlength="3000" placeholder="Storage, make-ahead tips, substitutions or reminders…">${esc(recipeDraft.notes)}</textarea></label><label class="switch-label"><input class="check" data-recipe-field="reviewed" type="checkbox" ${recipeDraft.reviewed?'checked':''}> I’ve reviewed this recipe and its batch yield</label>${existing?'<p class="list-note">Edits change this season’s plan immediately. Keep a backup before changing recipes you have already baked.</p>':''}<div class="modal-actions spread">${existing?`<button class="text-link danger-link" type="button" data-archive-recipe="${recipeDraft.id}">${recipeDraft.archived?'Restore recipe':'Archive recipe'}</button>`:'<span></span>'}<div class="page-buttons"><button class="btn quiet" type="button" data-action="close">Cancel</button><button class="btn" type="submit">${existing?'Save recipe':'Create recipe'}</button></div></div></form>`);
 $('#full-recipe-form').addEventListener('submit',saveRecipeDraft);
}
function saveRecipeDraft(e){
 e.preventDefault();const d=recipeDraft;
 if(!d.name.trim()){toast('Give your recipe a name.');return;}
 if(state.recipes.some(r=>r.id!==d.id&&r.name.trim().toLowerCase()===d.name.trim().toLowerCase())){toast('A recipe with that name already exists.');return;}
 if(!Number.isInteger(Number(d.yield))||d.yield<1){toast('Enter a whole-number batch yield of at least one.');return;}
 if(!d.lines.length||d.lines.some(l=>!state.ingredients.some(i=>i.id===l.ingredientId)||!Number.isFinite(Number(l.amount))||l.amount<=0)){toast('Add at least one ingredient and a positive amount for each row.');return;}
 d.name=d.name.trim();d.yield=Number(d.yield);d.lines=d.lines.map(l=>({ingredientId:l.ingredientId,amount:Number(l.amount),unit:l.unit}));
 const index=state.recipes.findIndex(r=>r.id===d.id);
 if(index<0)state.recipes.push(structuredClone(d));else state.recipes[index]=structuredClone(d);
 persist();$('#modal').close();render();toast('Recipe saved. Baking, shopping and cost totals updated.');
}
function drawRecipeLines(){ $('#recipe-lines').innerHTML=recipeDraft.lines.map(recipeLineHTML).join('');$('#recipe-live-summary').innerHTML=recipeLiveSummary(); }
function archiveRecipe(id){
 const r=state.recipes.find(r=>r.id===Number(id));if(r.archived){r.archived=false;persist();$('#modal').close();render();toast('Recipe restored for new requests.');return;}
 const orders=state.requests.filter(o=>o.items[r.id]>0&&!['Cancelled','Handed over'].includes(o.status));
 modal(modalHead('Archive '+r.name+'?','Keep your records. Remove this recipe from new requests.')+`<div class="modal-body"><p class="list-note">${orders.length?`${orders.length} current requests include this recipe. Their quantities remain visible and included in the plan; you can edit those requests if a replacement is needed.`:'No unfinished requests include this recipe.'} You can restore the recipe at any time.</p><div class="modal-actions"><button class="btn quiet" data-recipe="${r.id}">Keep recipe</button><button class="btn orange" data-confirm-archive-recipe="${r.id}">Archive recipe</button></div></div>`);
}
function ingredientDefaults(){return {id:nextId(state.ingredients),name:'',package:'',unit:'cup',unitsPerPackage:null,price:null,priceKind:'Missing',pantry:0,unitFactors:{},reviewed:false,archived:false};}
openIngredient=function(id,fromRecipe=false){
 const i=state.ingredients.find(i=>i.id===Number(id)&&id!=null);
 ingredientDraft={...structuredClone(i||ingredientDefaults()),fromRecipe};
 drawIngredientEditor();
};
function equivalenceRows(){const entries=Object.entries(ingredientDraft.unitFactors||{}).filter(([u,f])=>u!==ingredientDraft.unit);return entries.map(([u,f],n)=>`<div class="equivalence-row"><span>1 ${esc(ingredientDraft.unit)} =</span><input type="number" min="0.000001" step="any" value="${f>0?1/f:''}" required data-equivalent-amount="${u}" aria-label="Equivalent amount in ${u}"><select data-equivalent-unit="${u}" aria-label="Equivalent unit">${unitOptions(u)}</select><button class="remove-row" type="button" data-remove-equivalent="${u}" aria-label="Remove ${u} conversion">×</button></div>`).join('');}
function drawIngredientEditor(){
 const d=ingredientDraft,existing=state.ingredients.some(i=>i.id===d.id),uses=state.recipes.filter(r=>r.lines.some(l=>l.ingredientId===d.id)),p=plan.ingredientPlans.find(i=>i.id===d.id);
 modal(modalHead(existing?d.name:'Add an ingredient','One ingredient record keeps every recipe and shopping list consistent.')+`<form class="modal-body" id="full-ingredient-form"><div class="form-grid"><label class="field">Ingredient name<input data-ingredient-field="name" required maxlength="100" value="${esc(d.name)}" placeholder="e.g. All-purpose flour"></label><label class="field">Common recipe unit<select data-ingredient-field="unit">${unitOptions(d.unit)}</select></label><label class="field">Purchase package<input data-ingredient-field="package" maxlength="100" value="${esc(d.package)}" placeholder="e.g. 5 lb bag"></label><label class="field">${esc(unitLabels[d.unit])} in one package<input data-ingredient-field="unitsPerPackage" type="number" min="0.000001" step="any" value="${d.unitsPerPackage??''}" placeholder="Leave blank if not known yet"></label><label class="field">Price per package ($)<input data-ingredient-field="price" type="number" min="0" step="0.01" value="${d.price??''}" placeholder="Price not entered"></label><label class="field">Packages already in the pantry<input data-ingredient-field="pantry" type="number" min="0" step="any" value="${d.pantry||0}" placeholder="Partial packages are welcome"></label></div><div class="notice">Example: for a 5 lb flour bag, enter the verified cups in that bag if your common unit is cups. Package weight alone does not establish how many cups it contains. Blank values remain visibly incomplete.</div><div class="editor-section-head"><h3 class="section-title">Ingredient-specific equivalents</h3></div><p class="list-note">For recipes that use a different type of measurement, tell the app what one ${esc(d.unit)} of this ingredient equals. Cups, tablespoons and teaspoons already convert automatically; cups to grams need an ingredient-specific value.</p><div id="ingredient-equivalents">${equivalenceRows()}</div><button class="btn quiet small" type="button" data-action="add-equivalent">＋ Add an equivalent</button><label class="switch-label" style="margin-top:22px"><input class="check" data-ingredient-field="reviewed" type="checkbox" ${d.reviewed?'checked':''}> I’ve verified this ingredient’s package and measurements</label>${d.unitChangeNotice?`<div class="notice" style="margin-top:16px">${esc(d.unitChangeNotice)}</div>`:''}${p?`<details class="usage-details"><summary>Used by ${p.uses.length} recipes in the current bake plan</summary><ul class="checklist">${p.uses.map(u=>`<li><span>${esc(u.name)}</span><b>${u.incomplete?'Conversion needed':fmt(u.amount)+' '+esc(d.unit)}</b></li>`).join('')}</ul></details>`:existing?`<p class="list-note">Used in ${uses.length} saved recipes. Not needed by accepted requests in the current plan.</p>`:''}<div class="modal-actions spread">${existing?`<button class="text-link danger-link" type="button" data-archive-ingredient="${d.id}">${d.archived?'Restore ingredient':'Archive ingredient'}</button>`:'<span></span>'}<div class="page-buttons"><button class="btn quiet" type="button" data-action="${d.fromRecipe?'return-recipe':'close'}">${d.fromRecipe?'Back to recipe':'Cancel'}</button><button class="btn" type="submit">${existing?'Save ingredient':'Create ingredient'}</button></div></div></form>`);
 $('#full-ingredient-form').addEventListener('submit',saveIngredientDraft);
}
function saveIngredientDraft(e){
 e.preventDefault();const d=ingredientDraft;
 if(!d.name.trim()){toast('Give the ingredient a name.');return;}
 if(state.ingredients.some(i=>i.id!==d.id&&i.name.trim().toLowerCase()===d.name.trim().toLowerCase())){toast('That ingredient already exists. Choose it from the recipe list.');return;}
 if(d.unitsPerPackage!==null&&(!Number.isFinite(d.unitsPerPackage)||d.unitsPerPackage<=0)){toast('Package quantity must be positive or left blank.');return;}
 if(!Number.isFinite(d.pantry)||d.pantry<0||d.price!==null&&(!Number.isFinite(d.price)||d.price<0)){toast('Enter a valid price and pantry amount.');return;}
 if(Object.values(d.unitFactors).some(f=>!Number.isFinite(f)||f<=0)){toast('Complete each equivalent with a positive amount, or remove its row.');return;}
 const {fromRecipe,unitChangeNotice,...saved}=d;saved.name=saved.name.trim();
 const old=state.ingredients.find(i=>i.id===d.id);
 if(!old||old.price!==d.price){saved.priceKind=d.price===null?'Missing':'Manual';saved.priceDate=d.price===null?null:new Date().toLocaleDateString('en-US');}
 if(old)state.ingredients[state.ingredients.indexOf(old)]=saved;else state.ingredients.push(saved);
 persist();if(fromRecipe){recipeDraft.lines.push({ingredientId:saved.id,amount:1,unit:saved.unit});drawRecipeEditor();toast('Ingredient created and added to your recipe draft.');}else{$('#modal').close();render();toast('Ingredient saved. Related recipes and totals updated.');}
}
function archiveIngredient(id){const i=state.ingredients.find(i=>i.id===Number(id));const used=state.recipes.filter(r=>r.lines.some(l=>l.ingredientId===i.id)).length;if(i.archived){i.archived=false;persist();$('#modal').close();render();toast('Ingredient restored.');return;}modal(modalHead('Archive '+i.name+'?','Hide it from new ingredient selections without breaking saved recipes.')+`<div class="modal-body"><p class="list-note">${used} recipes use this ingredient. Their quantities and shopping calculations remain unchanged. Restore it at any time.</p><div class="modal-actions"><button class="btn quiet" data-ingredient="${i.id}">Keep ingredient</button><button class="btn orange" data-confirm-archive-ingredient="${i.id}">Archive ingredient</button></div></div>`);}
function downloadJSON(data,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function validateBackup(data){
 if(!data||!Array.isArray(data.recipes)||!Array.isArray(data.ingredients)||!Array.isArray(data.requests))throw Error('This file is not a Cookie Season kitchen backup.');
 for(const key of ['recipes','ingredients','requests'])if(new Set(data[key].map(x=>x.id)).size!==data[key].length)throw Error('The backup has duplicate record identifiers.');
 for(const i of data.ingredients)if(!Number.isInteger(i.id)||typeof i.name!=='string'||!CookieEngine.units.includes(CookieEngine.normalizeUnit(i.unit))||i.price!=null&&(!Number.isFinite(i.price)||i.price<0)||i.unitsPerPackage!=null&&(!Number.isFinite(i.unitsPerPackage)||i.unitsPerPackage<=0)||!Number.isFinite(i.pantry)||i.pantry<0)throw Error('An ingredient record is invalid.');
 CookieEngine.upgradeState(data,window.SOURCE_DATA);
 for(const i of data.ingredients)if(Object.entries(i.unitFactors||{}).some(([u,f])=>!CookieEngine.units.includes(u)||!Number.isFinite(f)||f<=0))throw Error('An ingredient equivalent is invalid.');
 for(const r of data.recipes)if(!Number.isInteger(r.id)||typeof r.name!=='string'||!Number.isInteger(r.yield)||r.yield<=0||!Array.isArray(r.lines)||!Number.isFinite(r.baked||0)||(r.baked||0)<0||r.lines.some(l=>!data.ingredients.some(i=>i.id===l.ingredientId)||!Number.isFinite(l.amount)||l.amount<=0||!CookieEngine.units.includes(l.unit)))throw Error('A recipe record is invalid.');
 for(const o of data.requests)if(typeof o.name!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(o.date)||!['Pending','Accepted','Packed','Handed over','Cancelled'].includes(o.status)||!o.items||Object.entries(o.items).some(([id,q])=>!data.recipes.some(r=>r.id===Number(id))||!Number.isInteger(q)||q<0))throw Error('A request record is invalid.');
 return data;
}
function resetConfirmation(){modal(modalHead('Start the demonstration over?','Your browser’s recipe corrections, requests and prices will be replaced.')+`<div class="modal-body"><p class="list-note">Download a backup first if you want to keep your changes. The imported recipes and illustrative prices will be restored, with an empty request list.</p><div class="modal-actions"><button class="btn quiet" data-action="backup">Download backup</button><button class="btn quiet" data-action="close">Keep my changes</button><button class="btn orange" data-action="confirm-reset">Reset demonstration</button></div></div>`);}
openOrphan=function(){const o=window.SOURCE_DATA.orphans[0];modal(modalHead(o.name,'Source entry needs a batch yield before it can become a recipe.')+`<div class="modal-body"><div class="notice">${esc(o.note)}</div><ul class="checklist">${o.lines.map(l=>`<li><span>${esc(state.ingredients.find(i=>i.id===l.ingredientId).name)}</span><b>${fmt(l.amount)} ${esc(CookieEngine.normalizeUnit(l.sourceUnit))}</b></li>`).join('')}</ul><div class="modal-actions"><button class="btn quiet" data-action="close">Leave for review</button><button class="btn" data-action="activate-orphan">Create recipe from this entry</button></div></div>`);};
const basicRender=render;
render=function(){plan=CookieEngine.calculate(state);if(['ingredients','settings'].includes(view)){$('#nav').innerHTML=NAV.map(([v,i,n])=>`<button data-go="${v}" class="${view===v?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#main').innerHTML=view==='ingredients'?ingredients():settings();}else basicRender();if(['overview','bake','shopping','requests'].includes(view))$('#main').insertAdjacentHTML('afterbegin',planningAlerts());if(view==='settings')$('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('This backup is too large.');return;}try{const data=validateBackup(JSON.parse(await file.text()));modal(modalHead('Restore this kitchen backup?','This replaces the current browser workspace.')+`<div class="modal-body"><p class="list-note">${data.recipes.length} recipes · ${data.ingredients.length} ingredients · ${data.requests.length} requests. Keep a backup of your current changes first.</p><div class="modal-actions"><button class="btn quiet" data-action="backup">Backup current kitchen</button><button class="btn quiet" data-action="close">Cancel</button><button class="btn" id="confirm-restore">Restore backup</button></div></div>`);$('#confirm-restore').onclick=()=>{state=data;persist();$('#modal').close();render();toast('Kitchen backup restored.');};}catch(error){toast(error.message||'Unable to read this backup.');}});};
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.recipeFilter){recipeFilter=d.recipeFilter;render();}else if(d.ingredientFilter){ingredientFilter=d.ingredientFilter;render();}
 else if(d.removeLine!=null){recipeDraft.lines.splice(Number(d.removeLine),1);drawRecipeLines();}
 else if(d.archiveRecipe!=null)archiveRecipe(d.archiveRecipe);
 else if(d.confirmArchiveRecipe!=null){state.recipes.find(r=>r.id===Number(d.confirmArchiveRecipe)).archived=true;persist();$('#modal').close();render();toast('Recipe archived. Existing requests are preserved.');}
 else if(d.archiveIngredient!=null)archiveIngredient(d.archiveIngredient);
 else if(d.confirmArchiveIngredient!=null){state.ingredients.find(i=>i.id===Number(d.confirmArchiveIngredient)).archived=true;persist();$('#modal').close();render();toast('Ingredient archived. Saved recipes are preserved.');}
 else if(d.removeEquivalent){delete ingredientDraft.unitFactors[d.removeEquivalent];$('#ingredient-equivalents').innerHTML=equivalenceRows();}
 else if(d.action==='new-recipe'){recipeDraft=newRecipeDraft();drawRecipeEditor();}
 else if(d.action==='new-ingredient')openIngredient(null);
 else if(d.action==='ingredient-from-recipe')openIngredient(null,true);
 else if(d.action==='return-recipe')drawRecipeEditor();
 else if(d.action==='add-recipe-line'){recipeDraft.lines.push({ingredientId:null,amount:1,unit:'cup'});drawRecipeLines();}
 else if(d.action==='add-equivalent'){const u=CookieEngine.units.find(u=>u!==ingredientDraft.unit&&!Object.hasOwn(ingredientDraft.unitFactors,u));if(!u){toast('All supported units already have equivalents.');return;}ingredientDraft.unitFactors[u]=null;$('#ingredient-equivalents').innerHTML=equivalenceRows();}
 else if(d.action==='backup'){downloadJSON({...state,backupCreatedAt:new Date().toISOString()},'Cookie-Season-Kitchen-Backup.json');toast('Kitchen backup downloaded.');}
 else if(d.action==='restore')$('#backup-file').click();
 else if(d.action==='reset-confirm')resetConfirmation();
 else if(d.action==='confirm-reset'){state=seed();CookieEngine.upgradeState(state,window.SOURCE_DATA);persist();$('#modal').close();render();toast('Demonstration restored.');}
 else if(d.action==='activate-orphan'){recipeDraft=newRecipeDraft();const o=window.SOURCE_DATA.orphans[0];recipeDraft.name=o.name;recipeDraft.yield='';recipeDraft.lines=o.lines.map(l=>({ingredientId:l.ingredientId,amount:l.amount,unit:CookieEngine.normalizeUnit(l.sourceUnit)}));drawRecipeEditor();}
});
document.addEventListener('input',e=>{
 const t=e.target,d=t.dataset;
 if(d.recipeField&&recipeDraft){recipeDraft[d.recipeField]=d.recipeField==='reviewed'?t.checked:d.recipeField==='yield'?Number(t.value):t.value;}
 if(d.lineField&&recipeDraft){const l=recipeDraft.lines[Number(d.lineIndex)];l[d.lineField]=d.lineField==='ingredientId'?t.value===''?null:Number(t.value):d.lineField==='amount'?Number(t.value):t.value;if(d.lineField==='ingredientId'){l.unit=state.ingredients.find(i=>i.id===l.ingredientId)?.unit||'cup';drawRecipeLines();}else $('#recipe-live-summary').innerHTML=recipeLiveSummary();}
 if(d.ingredientField&&ingredientDraft&&d.ingredientField!=='unit'){ingredientDraft[d.ingredientField]=d.ingredientField==='reviewed'?t.checked:['unitsPerPackage','price'].includes(d.ingredientField)?t.value===''?null:Number(t.value):d.ingredientField==='pantry'?Number(t.value):t.value;}
 if(d.equivalentAmount&&ingredientDraft){const n=Number(t.value);if(n>0)ingredientDraft.unitFactors[d.equivalentAmount]=1/n;else ingredientDraft.unitFactors[d.equivalentAmount]=null;}
 if(t.id==='ingredient-search'){query=t.value;const pos=t.selectionStart;render();$('#ingredient-search').focus();$('#ingredient-search').setSelectionRange(pos,pos);}
});
document.addEventListener('change',e=>{
 const t=e.target,d=t.dataset;
 if(d.ingredientField==='unit'&&ingredientDraft){const old=ingredientDraft.unit,newUnit=t.value,mult=CookieEngine.convert(1,old,newUnit,ingredientDraft);if(mult!=null){ingredientDraft.unitFactors=Object.fromEntries(Object.entries(ingredientDraft.unitFactors).filter(([,f])=>f>0).map(([u,f])=>[u,f*mult]));ingredientDraft.unitFactors[old]=mult;if(ingredientDraft.unitsPerPackage!=null)ingredientDraft.unitsPerPackage*=mult;ingredientDraft.unitChangeNotice=`Package quantity was converted from ${old} to ${newUnit}; recipe measurements remain intact.`;}else{ingredientDraft.unitFactors={};ingredientDraft.unitsPerPackage=null;ingredientDraft.unitChangeNotice=`No ${old}-to-${newUnit} equivalent is known. Enter the package quantity and add an equivalent for ${old} to keep existing recipes calculable.`;}ingredientDraft.unit=newUnit;ingredientDraft.reviewed=false;drawIngredientEditor();}
 if(d.equivalentUnit&&ingredientDraft){const old=d.equivalentUnit,newUnit=t.value;if(newUnit===ingredientDraft.unit||newUnit!==old&&Object.hasOwn(ingredientDraft.unitFactors,newUnit)){toast('Choose a different unit without an existing equivalent.');$('#ingredient-equivalents').innerHTML=equivalenceRows();return;}const f=ingredientDraft.unitFactors[old];delete ingredientDraft.unitFactors[old];ingredientDraft.unitFactors[newUnit]=f;$('#ingredient-equivalents').innerHTML=equivalenceRows();}
});
render();
